1	import { Block, Text } from "@prototyp/skeletor";
2	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
3	import { useAtom, useAtomValue } from "jotai";
4	import { AuthService } from "modules/auth/service/AuthService";
5	import { StorageAtoms } from "modules/storage/jotai/atoms";
6	import { useRef, useState } from "react";
7	import {
8	  Image,
9	  StyleSheet,
10	  TextInput,
11	  type TextInputKeyPressEvent,
12	} from "react-native";
13	import { GoBackHeader, Loading, ScreenLayout } from "shared/components";
14	import { Colors, TextSize } from "shared/styles";
15	import { offlineToastHelper } from "shared/utils";
16	
17	export const VerifyPin: React.FC<
18	  NativeStackScreenProps<Routes, "verifyPin">
19	> = ({ navigation, route }) => {
20	  const [pin, setPin] = useState<string[]>(["", "", "", ""]);
21	  const inputRefs = useRef<(TextInput | null)[]>([]);
22	  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
23	  const [screenLockAttempts, setScreenLockAttempts] = useAtom(
24	    StorageAtoms.screenLockAttempts,
25	  );
26	  const hasWrongAttempts = Number(screenLockAttempts) > 0;
27	  const isSettingsScreen = !!route.params?.isSettingsScreen;
28	  const [isLoggingOut, setIsLoggingOut] = useState(false);
29	
30	  const handlePinChange = async (text: string, index: number) => {
31	    if (text && !/^\d$/.test(text)) return;
32	
33	    const newPin = [...pin];
34	    newPin[index] = text;
35	    setPin(newPin);
36	
37	    // When 4th digit is entered, check if the PIN is correct
38	    if (index === 3) {
39	      const newPinString = newPin.join("");
40	      if (newPinString === screenLockPin) {
41	        setScreenLockAttempts("0");
42	        navigation.replace(isSettingsScreen ? "screenLockSettings" : "home");
43	        return;
44	      }
45	
46	      // If the user misses the last attempt, logout the user
47	      if (Number(screenLockAttempts) === 2) {
48	        try {
49	          setIsLoggingOut(true);
50	          offlineToastHelper("You have missed the last attempt.");
51	          await AuthService.logout();
52	          navigation.reset({
53	            index: 1,
54	            routes: [{ name: "welcome" }, { name: "login" }],
55	          });
56	        } catch (error) {
57	          console.error("Failed to logout: ", error);
58	          offlineToastHelper("Failed to logout");
59	        } finally {
60	          setIsLoggingOut(false);
61	        }
62	        return;
63	      }
64	
65	      setScreenLockAttempts(String(Number(screenLockAttempts) + 1));
66	      offlineToastHelper("PIN is incorrect. Please try again.");
67	      setPin(["", "", "", ""]);
68	      inputRefs.current[0]?.focus();
69	      return;
70	    }
71	
72	    // Move to next input if a digit was entered
73	    inputRefs.current[index + 1]?.focus();
74	  };
75	
76	  // Move to previous input on backspace
77	  const handleKeyPress = (e: TextInputKeyPressEvent, index: number) => {
78	    if (e.nativeEvent.key !== "Backspace" || pin[index] || index === 0) {
79	      return;
80	    }
81	
82	    const newPin = [...pin];
83	    newPin[index - 1] = "";
84	    setPin(newPin);
85	    inputRefs.current[index - 1]?.focus();
86	  };
87	
88	  return (
89	    <ScreenLayout type="modal">
90	      {isLoggingOut && <Loading text="Logging out..." />}
91	      <Block flex={1} align="center" gap={40}>
92	        {isSettingsScreen && <GoBackHeader margins={0} />}
93	        <Image
94	          height={100}
95	          width={100}
96	          source={require("assets/images/key.png")}
97	        />
98	        <Block gap={8}>
99	          <Text size={TextSize.large} textAlign="center">
100	            Enter your PIN
101	          </Text>
102	          <Text
103	            color={hasWrongAttempts ? Colors.warning : Colors.white80}
104	            textAlign="center"
105	          >
106	            {`You have ${3 - Number(screenLockAttempts)} attempts to enter the correct PIN.`}
107	          </Text>
108	          {hasWrongAttempts && (
109	            <Text color={Colors.warning} textAlign="center">
110	              If you forget this PIN, you will be logged out out of the app
111	            </Text>
112	          )}
113	        </Block>
114	
115	        <Block flexDirection="row" gap={12} pointerEvents="none">
116	          {pin.map((digit, index) => (
117	            <TextInput
118	              key={index}
119	              ref={(ref) => {
120	                inputRefs.current[index] = ref;
121	              }}
122	              style={styles.input}
123	              value={digit}
124	              onChangeText={(text) => handlePinChange(text, index)}
125	              onKeyPress={(e) => handleKeyPress(e, index)}
126	              keyboardType="number-pad"
127	              maxLength={1}
128	              selectTextOnFocus={false}
129	              autoFocus={index === 0}
130	            />
