import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { useSetAtom } from "jotai";
import { StorageAtoms } from "modules/storage/jotai/atoms";
import { useRef, useState } from "react";
import {
  Image,
  StyleSheet,
  TextInput,
  type TextInputKeyPressEvent,
} from "react-native";
import Toast from "react-native-toast-message";
import { GoBackHeader, ScreenLayout } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

export const SetupScreenLock: React.FC<
  NativeStackScreenProps<Routes, "setupScreenLock">
> = ({ navigation }) => {
  const [pin, setPin] = useState<string[]>(["", "", "", ""]);
  const [confirmPin, setConfirmPin] = useState<string[]>(["", "", "", ""]);
  const [isConfirming, setIsConfirming] = useState(false);
  const inputRefs = useRef<(TextInput | null)[]>([]);
  const confirmInputRefs = useRef<(TextInput | null)[]>([]);
  const setScreenLockPin = useSetAtom(StorageAtoms.screenLockPin);

  const handlePinChange = (text: string, index: number) => {
    if (text && !/^\d$/.test(text)) return;

    const newPin = [...pin];
    newPin[index] = text;
    setPin(newPin);

    // When 4th digit is entered, switch to confirmation mode
    if (index === 3) {
      setIsConfirming(true);
      confirmInputRefs.current[0]?.focus();
      inputRefs.current[0]?.focus();
      return;
    }

    // Move to next input if a digit was entered
    inputRefs.current[index + 1]?.focus();
  };

  const handleConfirmPinChange = (text: string, index: number) => {
    if (text && !/^\d$/.test(text)) return;

    const newConfirmPin = [...confirmPin];
    newConfirmPin[index] = text;
    setConfirmPin(newConfirmPin);

    const isComplete = newConfirmPin.every((digit) => digit !== "");

    // When 4th digit is entered, check if the PIN is complete
    if (index === 3 && isComplete) {
      const pinString = pin.join("");
      const confirmPinString = newConfirmPin.join("");

      if (pinString === confirmPinString) {
        Toast.show({
          type: "success",
          text1: "PIN set successfully.",
        });
        setScreenLockPin(pinString);
        navigation.popTo("settings");
        return;
      }

      offlineToastHelper("PINs don't match. Please try again.");

      setConfirmPin(["", "", "", ""]);
      confirmInputRefs.current[0]?.focus();
    }

    // Move to next input if a digit was entered
    confirmInputRefs.current[index + 1]?.focus();
  };

  // Move to previous input on backspace
  const handleKeyPress = (
    e: TextInputKeyPressEvent,
    index: number,
    isConfirming: boolean,
  ) => {
    const pinState = isConfirming ? confirmPin : pin;
    const refs = isConfirming ? confirmInputRefs : inputRefs;
    const setState = isConfirming ? setConfirmPin : setPin;

    if (e.nativeEvent.key !== "Backspace" || pinState[index] || index === 0) {
      return;
    }

    const newPin = [...pinState];
    newPin[index - 1] = "";
    setState(newPin);
    refs.current[index - 1]?.focus();
  };
  return (
    <ScreenLayout type="modal">
      <Block flex={1} align="center" gap={40}>
        <GoBackHeader margins={0} />
        <Image
          height={100}
          width={100}
          source={require("assets/images/key.png")}
        />
        <Block gap={8}>
          <Text size={TextSize.large} textAlign="center">
            {isConfirming ? "Confirm PIN" : "Choose PIN"}
          </Text>
          <Text color={Colors.white80} textAlign="center">
            Add extra security to your chats.
          </Text>
          <Text color={Colors.white80} textAlign="center">
            If you forget this PIN, you will be logged out out of the app.
          </Text>
        </Block>

        <Block gap={24} align="center" pointerEvents="none">
          {isConfirming ? (
            <Block flexDirection="row" gap={12}>
              {confirmPin.map((digit, index) => (
                <TextInput
                  key={index}
                  ref={(ref) => {
                    confirmInputRefs.current[index] = ref;
                  }}
                  style={styles.input}
                  value={digit}
                  onChangeText={(text) => handleConfirmPinChange(text, index)}
                  onKeyPress={(e) => handleKeyPress(e, index, true)}
                  keyboardType="number-pad"
                  maxLength={1}
                  autoFocus={index === 0}
                  selectTextOnFocus={false}
                />
              ))}
            </Block>
          ) : (
            <Block flexDirection="row" gap={12} pointerEvents="none">
              {pin.map((digit, index) => (
                <TextInput
                  key={index}
                  ref={(ref) => {
                    inputRefs.current[index] = ref;
                  }}
                  style={styles.input}
                  value={digit}
                  onChangeText={(text) => handlePinChange(text, index)}
                  onKeyPress={(e) => handleKeyPress(e, index, false)}
                  keyboardType="number-pad"
                  maxLength={1}
                  selectTextOnFocus={false}
                  autoFocus={index === 0}
                  editable={!isConfirming}
                />
              ))}
            </Block>
          )}
        </Block>
      </Block>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  input: {
    width: 60,
    height: 60,
    borderWidth: 1,
    borderColor: Colors.white50,
    borderRadius: 12,
    fontSize: 24,
    textAlign: "center",
    color: Colors.white,
    backgroundColor: "transparent",
  },
});

