// Capture the PIN value present at mount (MMKV is synchronous, so this is
// the real stored value). Used by the cold-start effect below so it fires
// exactly once regardless of later PIN changes.
const initialPinRef = useRef(screenLockPin);

// Cold-start: lock once on mount if a PIN was already stored.
// Using a ref means this effect has no reactive deps and won't fire again
// when the user sets up or changes their PIN later in the same session.
useEffect(() => {
  setIsLocked(!!initialPinRef.current);
}, [setIsLocked]);

// Unlock when the PIN is removed (disabled or logged out).
// Intentionally does NOT lock when a PIN is added/changed — the user is
// already authenticated at that point and shouldn't be locked out.
useEffect(() => {
  if (!screenLockPin) setIsLocked(false);
}, [screenLockPin, setIsLocked]);

